const ValidationContext=React.createContext({errors:{},touch:()=>{}});
const API=async(path,body)=>{if(isWorkspace)return workspaceAPI(path,body);const r=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Không thể kết nối.');return v};
const cx=(...v)=>v.filter(Boolean).join(' ');
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const shortMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n||0);
function Button({children,icon:Icon,variant='',...props}){return <button className={'btn '+variant} {...props}>{Icon&&<Icon size={18}/>} {children}</button>}
function Field({label,children,required,validationKey,...props}){const context=useContext(ValidationContext),id=useId(),error=context.errors[validationKey];const accessibility={'data-validation-key':validationKey,'aria-invalid':error?true:undefined,'aria-describedby':error?id:undefined,'aria-label':label};return <label className={'field'+(error?' invalid':'')} onBlurCapture={()=>validationKey&&context.touch(validationKey)}><span>{label}{required&&<b className="required"> *</b>}</span>{children?React.cloneElement(children,accessibility):<input {...props} {...accessibility} required={required}/>} {error&&<small className="field-error" id={id}>{error}</small>}</label>}

function Badge({order,children,tone}){return <span className={'badge '+(tone||(order?.stage===0?'gray':order?.stage===2?'amber':order?.stage>=9?'green':'blue'))}>{children||status(order)}</span>}
function Panel({title,extra,children,className=''}){const icons={'Thông tin khách hàng':Users,'Thông tin đơn hàng':Receipt,'Sản phẩm gốc':Package,'Sản phẩm bổ sung':Plus,'Quà tặng':StarIcon,'Ghi chú đơn hàng':NotePencil,'Thông tin thanh toán':Wallet,'Thông tin giao hàng':Truck,'Chứng từ & các lần thanh toán':Receipt,'Chứng từ thanh toán':Receipt,'Trao đổi theo đơn hàng':ChatCircleDots,'Tiến độ đơn hàng':Clock};const Icon=icons[title];return <section className={'panel '+className}>{title&&<div className="panel-head"><h3 className="panel-heading">{Icon&&<span className="section-icon"><Icon size={18} weight="duotone"/></span>}{title}</h3>{extra}</div>}{children}</section>}
const StarIcon=({size})=><Package size={size} weight="duotone"/>;

function OrderOverview({data,onFilter,onOpen,onCreate,onCustomer}){const [year,setYear]=useState(today().slice(0,4));return <><div className="page-title"><div><h1>Tổng quan đơn hàng</h1><p>Theo dõi tăng trưởng và bộ phận đang phụ trách xử lý.</p></div><div className="actions"><QuickCreate onCreate={onCreate}/><Button onClick={()=>onFilter('all')}>Đơn hàng chưa hoàn thành</Button></div></div><div className="list-overview order-overview"><MonthlyActivity orders={data.orders} mode="orders" year={year} onYear={setYear}/><OrderOutcomes orders={data.orders}/></div><ApprovedOrderHistory key={year} data={data} year={year} onOpen={onOpen}/></>}
function QuickCreate({onCreate,onCustomer}){return (onCreate||onCustomer)?<div className="actions quick-create">{onCustomer&&<Button icon={UserPlus} onClick={onCustomer}>Tạo khách hàng</Button>}{onCreate&&<Button variant="primary" icon={Plus} onClick={onCreate}>Tạo đơn hàng</Button>}</div>:null}
function Empty({text='Không có dữ liệu phù hợp',children}){return <div className="empty"><Receipt size={32}/><h3>{text}</h3>{children}</div>}
function Modal({title,onClose,children,wide=false}){const ref=useRef(null);useEffect(()=>{const previous=document.activeElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const node=ref.current;const editable=node.querySelector('input:not([type="checkbox"]),textarea');if(editable)editable.focus();else node.focus();const f=e=>{if(e.key==='Escape'){e.preventDefault();onClose()}if(e.key==='Tab'){const all=[...node.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.getClientRects().length);const first=all[0],last=all.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===node)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',f);return()=>{document.removeEventListener('keydown',f);document.body.style.overflow=overflow;previous?.focus()}},[]);return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section ref={ref} tabIndex={-1} className={cx('modal',wide&&'wide')} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button aria-label="Đóng" className="icon-btn" onClick={onClose}><X size={22}/></button></div>{children}</section></div>}

