 useEffect(()=>{if(!isWorkspace||page==='create'||page==='settings'||modal)return;const refresh=()=>{if(!mutationLock.current&&!draftStatus.current)API('/state').then(setData).catch(()=>{})};const timer=setInterval(refresh,30000);window.addEventListener('focus',refresh);return()=>{clearInterval(timer);window.removeEventListener('focus',refresh)}},[page,modal]);
