 const run=async(fn,onError)=>{if(mutationLock.current)return;mutationLock.current=true;setBusy(true);try{await fn();return true}catch(e){onError?.(e);notify(e.message,true);return false}finally{mutationLock.current=false;setBusy(false)}};
