 const action=(id,action,extra={})=>run(async()=>{setData(await API(`/orders/${id}/action`,{action,version:data.orders.find(o=>o.id===id)?.version,...extra}));setModal(null);notify(action==='payment'?'Đã gửi chứng từ, chờ Kế toán xác nhận.':'Đã lưu thay đổi.');if(action==='delete')go('orders')});
