 {page==='create'&&editor&&<OrderEditor key={`${editor.id||'new'}-${editorKey}`} order={editor} data={data} busy={busy} onChoose={createOrder} onUpdate={setData} draftStatus={draftStatus} onCancel={()=>go('orders')} onCustomer={()=>setModal({type:'customer'})} onSave={(o,submit,onError)=>run(async()=>{const v=await API('/orders',{...o,submit});localStorage.removeItem(`hq-draft:${user.id||'demo'}:${o.customerId}`);draftStatus.current=false;setData(v.state);setSelected(v.id);setPage('detail');setEditor(null);notify(o.stage>0?'Đã lưu chỉnh sửa ngoại lệ và lịch sử.':submit?'Đã gửi yêu cầu duyệt. Đơn hàng đã được khóa.':'Đã lưu bản nháp.')},onError)}/>}
