 {['edit-request','grant-edit','rework','message'].includes(modal?.type)&&<TextModal title={modal.type==='grant-edit'?'Cấp quyền sửa đơn chờ duyệt':modal.type==='edit-request'?'Yêu cầu cấp quyền chỉnh sửa':'Yêu cầu xưởng sửa lại'} onClose={()=>setModal(null)} busy={busy} onSend={text=>action(order.id,modal.type,{text})}/>}
